const event = $json.body ?? $json;
if (event.event_type !== 'workflow.review_resolved') throw new Error('Unexpected event type');
const resolution = event.review_case?.resolution;
const notification = resolution === 'ACCEPT_EXCEPTION' ? 'Exception accepted' : resolution === 'REJECT' ? 'Invoice rejected' : 'Unknown resolution';
return [{ json: { notification, event } }];
